import NavMenu from "./NavMenu";

export function Videos(){
    return(
        <div>
            <NavMenu></NavMenu>
            <br></br>
            <h1>
                Nem csak képek, hanem videókat is készítek egyes koncepciókról.
            </h1>
            <p>
                Ezek videóknak a célja, hogy a koncepció minél rövidebb idő alatt elsajátítható legyen, ezért is igyekeztem a hosszukat levágni 10 másodperc alá. Itt van néhány példa:
            </p>
             <h2 class="text-center">
                Összeadás:
            </h2>
            <video class='text-center' style={{width:'50%', height:'50%'}}>
                <source src={require("../assets/Addition.mp4")} />
            </video>
        </div>
    );
}

export default Videos;
